effect.shader:
vec4 tex(vec2 p){ return texture2DCv(inputImg.texture, p); }
void main(){
vec2 uv = acScreenNorm;
vec4 src = tex(uv);
vec2 st = 1.0 / max(acScreenSize, vec2(1.0));
float m = src.a;
for (int i = 0; i < 16; i++){
  float a = 6.28318530718 * float(i) / 16.0;
  m = max(m, tex(uv + vec2(cos(a), sin(a)) * radius * st).a);
}
for (int i = 0; i < 8; i++){
  float a = 6.28318530718 * float(i) / 8.0 + 0.3926990817;
  m = max(m, tex(uv + vec2(cos(a), sin(a)) * radius * 0.55 * st).a);
}
gl_FragColor = vec4(src.rgb, mix(src.a, max(src.a, m), mixAmt));
}
